"use client"

import { createParts, usePart, type PartProps } from "@ui-sdk/react/primitive"
import { createContext, use, type ComponentProps } from "react"

import {
  createScrollAreaController,
  scrollArea,
  type Orientation,
  type ScrollAreaScrollbarState,
  type ScrollAreaThumbState,
} from "@/components/ui/scroll-area-primitive"
import { cnState } from "@/lib/utils"

const parts = /* @__PURE__ */ createParts(scrollArea, {
  root: "div",
  viewport: "div",
  content: "div",
  corner: "div",
  "scroll-to-end": "button",
})

const OrientationContext = /* @__PURE__ */ createContext<Orientation>("vertical")

/** The root sets `position: relative` inline, so a sticky or absolute root takes `sticky!` or `absolute!`. */
function ScrollArea({ className, ...props }: ComponentProps<typeof parts.Root>) {
  return <parts.Root className={cnState("relative overflow-hidden", className)} {...props} />
}

function ScrollAreaViewport({ className, ...props }: ComponentProps<typeof parts.Viewport>) {
  return (
    <parts.Viewport
      className={cnState(
        "size-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        className,
      )}
      {...props}
    />
  )
}

// Functions rather than `const ScrollAreaContent = parts.Content`: a property read at the top of a module counts as a
// side effect to bundlers, which then keep the whole scroll area in every bundle that imports this file.
function ScrollAreaContent(props: ComponentProps<typeof parts.Content>) {
  return <parts.Content {...props} />
}

function ScrollAreaCorner(props: ComponentProps<typeof parts.Corner>) {
  return <parts.Corner {...props} />
}

function ScrollAreaScrollToEnd(props: ComponentProps<typeof parts.ScrollToEnd>) {
  return <parts.ScrollToEnd {...props} />
}

/**
 * A scrollbar for one axis; without children it holds its thumb. `data-agent-hidden` on it leaves its scroll area out
 * of agents' snapshot and keeps what it holds: for one inside a component agents already know by name, which the
 * scroll area would otherwise repeat, making `query({ within })` with that name ambiguous.
 */
function ScrollAreaScrollbar({
  orientation = "vertical",
  className,
  children,
  ...props
}: PartProps<"div", ScrollAreaScrollbarState> & { orientation?: Orientation }) {
  return (
    <OrientationContext value={orientation}>
      {usePart(
        scrollArea,
        "scrollbar",
        { id: orientation, orientation },
        {
          ...props,
          className: cnState(
            // oxlint-disable-next-line p-otero/spacing-tokens -- the thumb's inset inside the size-2 track: geometry, not spacing
            "group/scrollbar flex touch-none p-0.5 opacity-0 transition-opacity select-none data-visible:opacity-100 data-[orientation=horizontal]:h-2 data-[orientation=horizontal]:flex-col data-[orientation=vertical]:w-2",
            className,
          ),
          children: children ?? <ScrollAreaThumb />,
        },
      )}
    </OrientationContext>
  )
}

function ScrollAreaThumb({ className, ...props }: PartProps<"div", ScrollAreaThumbState>) {
  const orientation = use(OrientationContext)
  return usePart(
    scrollArea,
    "thumb",
    { id: orientation, orientation },
    {
      ...props,
      className: cnState(
        "relative flex-1 rounded-full bg-muted-foreground/25 transition-colors group-hover/scrollbar:bg-muted-foreground/50 data-dragging:bg-muted-foreground/70",
        className,
      ),
    },
  )
}

export {
  createScrollAreaController,
  ScrollArea,
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaScrollbar,
  ScrollAreaScrollToEnd,
  ScrollAreaThumb,
  ScrollAreaViewport,
}

import { createController, css, definePrimitive, live } from "@ui-sdk/core"

import {
  mainAxis,
  type Axis,
  type ScrollAreaModel,
  type ScrollAreaScrollOptions,
  type ScrollAreaType,
} from "@/components/ui/scroll-area-model"
import { createScrollView } from "@/components/ui/scroll-area-view"

type ScrollAreaController = {
  /** Scrolls to the end: the bottom, or the inline end when only the horizontal axis overflows. */
  scrollToEnd: (options?: ScrollAreaScrollOptions) => void
  /** Scrolls to the start: the top, or the inline start when only the horizontal axis overflows. */
  scrollToStart: (options?: ScrollAreaScrollOptions) => void
  /** Whether the view is at the end now, even in a scroll event, before the attributes catch up. */
  isAtEnd: () => boolean
  /** Whether the view is at the start now, even in a scroll event, before the attributes catch up. */
  isAtStart: () => boolean
  /** Whether the view follows the end as the content grows, with `stickToEnd`. */
  isSticking: () => boolean
}

type ScrollAreaOptions = {
  /** When the scrollbars show: "auto" while the content overflows, "always", "scroll" while scrolling, "hover" (default) also while hovered. */
  type?: ScrollAreaType
  /** How long scrollbars stay after they stop being needed, in ms, with "scroll" and "hover". Defaults to 600. */
  scrollHideDelay?: number
  /** Keeps the end in view while the content grows; scrolling toward the start lets go. */
  stickToEnd?: boolean
  /** Drives it from anywhere. Create one with `createScrollAreaController()`. */
  controller?: ScrollAreaController
}

type Orientation = "horizontal" | "vertical"
type ScrollAreaScrollbarState = {
  orientation: Orientation
  visible: boolean
  scrolling: boolean
  hovering: boolean
  dragging: boolean
}
type ScrollAreaThumbState = { orientation: Orientation; dragging: boolean }

function createScrollAreaController() {
  return createController<ScrollAreaController>()
}

const axisOf = (orientation: unknown): Axis => (orientation === "horizontal" ? "x" : "y")
const orientationOf = (orientation: unknown): Orientation => (orientation === "horizontal" ? "horizontal" : "vertical")
const atStart = (state: ScrollAreaModel) => (mainAxis(state) === "x" ? state.atXStart : state.atYStart)
const atEnd = (state: ScrollAreaModel) => (mainAxis(state) === "x" ? state.atXEnd : state.atYEnd)
const hasScrollbars = (state: ScrollAreaModel) => state.scrollbarsX + state.scrollbarsY > 0
const endButtonShown = (state: ScrollAreaModel) => !atEnd(state) && !(state.stickToEnd && state.sticking)
const flag = (value: boolean) => (value ? "" : undefined)

const areaState = (state: ScrollAreaModel) => ({
  overflowX: state.overflowX,
  overflowY: state.overflowY,
  atStart: atStart(state),
  atEnd: atEnd(state),
  scrolling: state.scrollingX || state.scrollingY,
  hovering: state.hovering,
  sticking: state.stickToEnd && state.sticking,
})
const overflowAttrs = (state: ScrollAreaModel) => ({
  "data-overflow-x": flag(state.overflowX),
  "data-overflow-y": flag(state.overflowY),
})
const scrollAttrs = /* @__PURE__ */ live<ScrollAreaModel, unknown, unknown>((state) => ({
  "data-at-start": flag(atStart(state)),
  "data-at-end": flag(atEnd(state)),
  "data-at-x-start": flag(state.atXStart),
  "data-at-x-end": flag(state.atXEnd),
  "data-at-y-start": flag(state.atYStart),
  "data-at-y-end": flag(state.atYEnd),
  "data-scrolling": flag(state.scrollingX || state.scrollingY),
  "data-hovering": flag(state.hovering),
  "data-sticking": flag(state.stickToEnd && state.sticking),
}))
// The root's frame variables are registered as not inherited; this keeps an unregistered fallback from reaching the content.
const contentShield = /* @__PURE__ */ Object.fromEntries(
  ["x", "y"].flatMap((axis) =>
    [`overflow-${axis}-start`, `overflow-${axis}-end`, `progress-${axis}`].map((name) => [
      `--scroll-area-${name}`,
      "initial",
    ]),
  ),
)

const settings = (options: ScrollAreaOptions) => ({
  type: options.type ?? "hover",
  scrollHideDelay: options.scrollHideDelay ?? 600,
  stickToEnd: options.stickToEnd ?? false,
})

const scrollArea = /* @__PURE__ */ definePrimitive({
  name: "scroll-area",
  options: {
    type: "string",
    scrollHideDelay: "number",
    stickToEnd: "boolean",
    controller: "value",
  },
  state: (options: ScrollAreaOptions): ScrollAreaModel => ({
    ...settings(options),
    scrollbarsX: 0,
    scrollbarsY: 0,
    counted: false,
    overflowX: false,
    overflowY: false,
    atXStart: true,
    atXEnd: true,
    atYStart: true,
    atYEnd: true,
    scrollingX: false,
    scrollingY: false,
    hovering: false,
    visibleX: false,
    visibleY: false,
    dragging: null,
    sticking: Boolean(options.stickToEnd),
  }),
  live: [
    "atXStart",
    "atXEnd",
    "atYStart",
    "atYEnd",
    "scrollingX",
    "scrollingY",
    "hovering",
    "visibleX",
    "visibleY",
    "dragging",
    "sticking",
  ],
  sync: settings,
  controlled: [],
  api: (context) => {
    const { store } = context
    const view = createScrollView(store)
    let { stickToEnd, type, scrollHideDelay } = store.get()
    let destroyed = false
    context.onDestroy(() => (destroyed = true))
    context.onDestroy(
      store.subscribe(() => {
        const state = store.get()
        if (state.stickToEnd === stickToEnd && state.type === type && state.scrollHideDelay === scrollHideDelay) return
        if (state.stickToEnd !== stickToEnd) store.set({ sticking: state.stickToEnd })
        ;({ stickToEnd, type, scrollHideDelay } = state)
        queueMicrotask(() => destroyed || view.refresh())
      }),
    )
    return {
      scrollToEnd: (options?: ScrollAreaScrollOptions) => view.scrollToEdge("end", options),
      scrollToStart: (options?: ScrollAreaScrollOptions) => view.scrollToEdge("start", options),
      isAtEnd: () => view.isAt("end") ?? atEnd(store.get()),
      isAtStart: () => view.isAt("start") ?? atStart(store.get()),
      isSticking: () => store.get().stickToEnd && store.get().sticking,
      internal: view,
    }
  },
  slots: (slot) => ({
    root: slot({
      state: areaState,
      attrs: (state) => ({
        ...overflowAttrs(state),
        style: "position:relative",
      }),
      live: scrollAttrs,
      bind: (el, { api }) => api.internal.bindRoot(el),
    }),
    // The native scroller. Its own scrollbars hide once custom ones are on the page; on the server, custom ones are assumed.
    viewport: slot({
      state: areaState,
      attrs: (state) => ({
        ...overflowAttrs(state),
        style: css({
          overflow: "auto",
          "scrollbar-width": !state.counted || hasScrollbars(state) ? "none" : undefined,
        }),
      }),
      live: scrollAttrs,
      bind: (el, { api }) => api.internal.bindViewport(el),
    }),
    // Wider than the viewport only with a horizontal scrollbar, so text truncates as usual otherwise.
    content: slot({
      state: areaState,
      attrs: (state) => ({
        ...overflowAttrs(state),
        style: css({
          "min-width": state.scrollbarsX > 0 ? "fit-content" : undefined,
          ...contentShield,
        }),
      }),
      live: scrollAttrs,
    }),
    // Hidden from assistive technology: the viewport scrolls natively, which screen readers already use.
    scrollbar: slot<{ orientation?: Orientation }, ScrollAreaScrollbarState>({
      props: { orientation: "string" },
      state: (state, { props }) => {
        const axis = axisOf(props.orientation)
        return {
          orientation: orientationOf(props.orientation),
          visible: axis === "x" ? state.visibleX : state.visibleY,
          scrolling: axis === "x" ? state.scrollingX : state.scrollingY,
          hovering: state.hovering,
          dragging: state.dragging === axis,
        }
      },
      attrs: (state, { props }) => {
        const axis = axisOf(props.orientation)
        const overflow = axis === "x" ? state.overflowX : state.overflowY
        return {
          "aria-hidden": "true",
          "data-orientation": orientationOf(props.orientation),
          ...overflowAttrs(state),
          style: css({
            position: "absolute",
            "touch-action": "none",
            "user-select": "none",
            "-webkit-user-select": "none",
            ...(axis === "y"
              ? {
                  top: 0,
                  bottom: "var(--scroll-area-corner-height,0px)",
                  "inset-inline-end": 0,
                }
              : {
                  bottom: 0,
                  "inset-inline-start": 0,
                  "inset-inline-end": "var(--scroll-area-corner-width,0px)",
                }),
            display: overflow || state.type === "always" ? undefined : "none",
          }),
        }
      },
      live: live((state, { props }) => {
        const axis = axisOf(props.orientation)
        const visible = axis === "x" ? state.visibleX : state.visibleY
        return {
          "data-visible": flag(visible),
          "data-scrolling": flag(axis === "x" ? state.scrollingX : state.scrollingY),
          "data-hovering": flag(state.hovering),
          "data-dragging": flag(state.dragging === axis),
          // A hidden scrollbar must not catch presses meant for the content under it.
          style: visible ? undefined : "pointer-events:none",
        }
      }),
      bind: (el, part) => part.api.internal.bindScrollbar(el, axisOf(part.props.orientation)),
    }),
    // Sized and moved by the CSS variables its scrollbar holds.
    thumb: slot<{ orientation?: Orientation }, ScrollAreaThumbState>({
      props: { orientation: { kind: "string", from: "scrollbar" } },
      state: (state, { props }) => ({
        orientation: orientationOf(props.orientation),
        dragging: state.dragging === axisOf(props.orientation),
      }),
      attrs: (state, { props }) => {
        const axis = axisOf(props.orientation)
        const overflow = axis === "x" ? state.overflowX : state.overflowY
        return {
          "data-orientation": orientationOf(props.orientation),
          style: css(
            axis === "y"
              ? {
                  height: "var(--scroll-area-thumb-height)",
                  transform: "translate3d(0,var(--scroll-area-thumb-offset,0px),0)",
                  display: overflow ? undefined : "none",
                }
              : {
                  width: "var(--scroll-area-thumb-width)",
                  transform: "translate3d(var(--scroll-area-thumb-offset,0px),0,0)",
                  display: overflow ? undefined : "none",
                },
          ),
        }
      },
      live: live((state, { props }) => ({
        "data-dragging": flag(state.dragging === axisOf(props.orientation)),
      })),
      bind: (el, part) => part.api.internal.bindThumb(el, axisOf(part.props.orientation)),
    }),
    // Where the two scrollbars meet, there only while both show.
    corner: slot({
      attrs: (state) => ({
        "aria-hidden": "true",
        style: css({
          position: "absolute",
          bottom: 0,
          "inset-inline-end": 0,
          width: "var(--scroll-area-corner-width)",
          height: "var(--scroll-area-corner-height)",
          display:
            state.overflowX && state.overflowY && state.scrollbarsX > 0 && state.scrollbarsY > 0 ? undefined : "none",
        }),
      }),
    }),
    // Scrolls to the end, like "Jump to latest" in a chat. Inert while it shouldn't show, so it fades out without focus.
    "scroll-to-end": slot({
      state: (state) => ({ visible: endButtonShown(state) }),
      attrs: () => ({ type: "button" }),
      live: live((state) => ({
        "data-visible": flag(endButtonShown(state)),
        inert: flag(!endButtonShown(state)),
      })),
      press: ({ api, el }, event) => {
        if (el && el.ownerDocument.activeElement === el) api.internal.focusViewport()
        api.scrollToEnd()
        event?.preventDefault()
      },
    }),
  }),
  agent: { actions: ["scrollToStart", "scrollToEnd"] },
})

export {
  createScrollAreaController,
  scrollArea,
  type Orientation,
  type ScrollAreaController,
  type ScrollAreaOptions,
  type ScrollAreaScrollbarState,
  type ScrollAreaThumbState,
}

import { isRTL } from "@ui-sdk/core"

import {
  createStyleWriter,
  edgeTolerance,
  edgesOf,
  focusViewport,
  isEditing,
  listen,
  mainAxis,
  maxScroll,
  names,
  overflows,
  prefersReducedMotion,
  registerFrameVariables,
  scrollbarShown,
  scrollsInside,
  startwardKeys,
  thumbGeometry,
  type Axis,
  type Metrics,
  type ScrollAreaModel,
  type ScrollAreaScrollOptions,
  type ScrollAreaStore,
} from "@/components/ui/scroll-area-model"
import { createScrollbarInput } from "@/components/ui/scroll-area-pointer"
import { bindTabStop } from "@/components/ui/scroll-area-tab-stop"

const scrollEndDelay = 150
const axes = ["x", "y"] as const
const preventDefault = (event: Event) => event.preventDefault()

function createScrollView(store: ScrollAreaStore) {
  let root: HTMLElement | undefined
  let viewport: HTMLElement | undefined
  const host = () => viewport?.ownerDocument.defaultView ?? window
  const scrollbars = new Set<{ el: HTMLElement; axis: Axis }>()
  const track = { x: 0, y: 0 }
  const thickness = { x: 0, y: 0 }
  let rtl = false
  const metrics: Record<Axis, Metrics> = {
    x: { position: 0, client: 0, scroll: 0 },
    y: { position: 0, client: 0, scroll: 0 },
  }
  const previous = { x: Number.NaN, y: Number.NaN }
  const { write, clear } = createStyleWriter()
  let stuckTo = Number.NaN
  let touchY: number | null = null
  let pressed = false
  let easing = 0
  const scrollEnds = { x: 0, y: 0 }
  const lastScroll = { x: 0, y: 0 }
  const hideTimers = { x: 0, y: 0 }

  function measure() {
    const el = viewport
    if (!el) return
    metrics.y.position = el.scrollTop
    metrics.y.client = el.clientHeight
    metrics.y.scroll = el.scrollHeight
    const left = el.scrollLeft
    if (left !== 0 && left < 0 !== rtl) rtl = isRTL(el)
    metrics.x.position = rtl ? -left : left
    metrics.x.client = el.clientWidth
    metrics.x.scroll = el.scrollWidth
  }

  function setFlag<K extends keyof ScrollAreaModel>(key: K, value: ScrollAreaModel[K]) {
    if (store.get()[key] !== value) store.set({ [key]: value } as Partial<ScrollAreaModel>)
  }

  // Reads every metric, then writes what changed, in the scroll event itself. Writing in an animation frame, as UI SDK
  // does, cost a 20,000-line DiffView 9 ms more per key press at 4× CPU in Chrome.
  function update(resized = false) {
    if (!viewport) return
    measure()
    if (resized) follow()
    const state = store.get()
    let patch: Partial<ScrollAreaModel> | undefined
    const set = <K extends keyof ScrollAreaModel>(key: K, value: ScrollAreaModel[K]) => {
      if (state[key] !== value) (patch ??= {})[key] = value
    }
    for (const axis of axes) {
      const axisMetrics = metrics[axis]
      const name = names[axis]
      const delta = Number.isNaN(previous[axis]) ? 0 : axisMetrics.position - previous[axis]
      previous[axis] = axisMetrics.position
      const edges = edgesOf(axisMetrics)
      set(name.overflow, overflows(axisMetrics))
      set(name.atStart, edges.atStart)
      set(name.atEnd, edges.atEnd)
      if (root) {
        write(root, name.before, edges.before)
        write(root, name.after, edges.after)
        write(root, name.progress, edges.progress, "")
      }
      writeThumb(axis)
      if (delta === 0) continue
      const ownScroll = axis === "y" && Math.abs(axisMetrics.position - stuckTo) < edgeTolerance
      if (!ownScroll) {
        lastScroll[axis] = performance.now()
        set(name.scrolling, true)
        scrollEnds[axis] ||= host().setTimeout(() => endScroll(axis), scrollEndDelay)
      }
      if (axis === "y" && state.stickToEnd) {
        const atEnd = edges.after < edgeTolerance
        set("sticking", state.sticking ? atEnd || delta >= 0 : atEnd && delta > 0)
      }
    }
    writeCorner(patch?.overflowX ?? state.overflowX, patch?.overflowY ?? state.overflowY)
    if (patch) store.set(patch)
    if (patch || resized) refreshVisibility()
  }

  function writeThumb(axis: Axis) {
    const geometry = thumbGeometry(metrics[axis], track[axis])
    for (const scrollbar of scrollbars) {
      if (scrollbar.axis !== axis) continue
      write(scrollbar.el, names[axis].thumbSize, geometry.size)
      write(scrollbar.el, "--scroll-area-thumb-offset", axis === "x" && rtl ? -geometry.offset : geometry.offset)
    }
  }

  function writeCorner(overflowX: boolean, overflowY: boolean) {
    if (!root) return
    const state = store.get()
    const both = overflowX && overflowY && state.scrollbarsX > 0 && state.scrollbarsY > 0
    write(root, "--scroll-area-corner-width", both ? thickness.y : 0)
    write(root, "--scroll-area-corner-height", both ? thickness.x : 0)
  }

  function endScroll(axis: Axis) {
    const elapsed = performance.now() - lastScroll[axis]
    if (elapsed < scrollEndDelay) {
      scrollEnds[axis] = host().setTimeout(() => endScroll(axis), scrollEndDelay - elapsed)
      return
    }
    scrollEnds[axis] = 0
    setFlag(names[axis].scrolling, false)
    refreshVisibility()
  }

  function refreshVisibility() {
    const state = store.get()
    for (const axis of axes) {
      const name = names[axis]
      if (scrollbarShown(state, axis)) {
        host().clearTimeout(hideTimers[axis])
        hideTimers[axis] = 0
        setFlag(name.visible, true)
        continue
      }
      if (!state[name.visible] || hideTimers[axis]) continue
      const delay = state.type === "scroll" || state.type === "hover" ? state.scrollHideDelay : 0
      if (delay <= 0) {
        setFlag(name.visible, false)
        continue
      }
      hideTimers[axis] = host().setTimeout(() => {
        hideTimers[axis] = 0
        setFlag(name.visible, false)
        refreshVisibility()
      }, delay)
    }
  }

  function follow() {
    const state = store.get()
    if (!viewport || !state.stickToEnd || !state.sticking || state.dragging || pressed || touchY !== null || easing) {
      return
    }
    const max = maxScroll(metrics.y)
    if (max - metrics.y.position < edgeTolerance) return
    stuckTo = max
    viewport.scrollTo({ top: max, behavior: "instant" })
    metrics.y.position = viewport.scrollTop
  }

  function scrollTo(axis: Axis, position: number, behavior: ScrollBehavior = "instant") {
    if (!viewport) return
    if (axis === "y") viewport.scrollTo({ top: position, behavior })
    else viewport.scrollTo({ left: rtl ? -position : position, behavior })
  }

  function stopEasing() {
    if (!easing) return
    host().cancelAnimationFrame(easing)
    easing = 0
  }

  function release() {
    stopEasing()
    if (store.get().sticking && metrics.y.position > 0) store.set({ sticking: false })
  }

  function easeToEnd() {
    const step = () => {
      easing = 0
      if (!viewport) return
      measure()
      const gap = maxScroll(metrics.y) - metrics.y.position
      if (gap < edgeTolerance) return update()
      scrollTo("y", metrics.y.position + Math.max(1, gap * 0.2))
      easing = host().requestAnimationFrame(step)
    }
    easing = host().requestAnimationFrame(step)
  }

  function scrollToEdge(edge: "start" | "end", { behavior = "smooth" }: ScrollAreaScrollOptions = {}) {
    if (!viewport) return
    const axis = mainAxis(store.get())
    if (axis === "x") rtl = isRTL(viewport)
    measure()
    const smooth = behavior === "smooth" && !prefersReducedMotion()
    stopEasing()
    if (edge === "end" && axis === "y" && store.get().stickToEnd) setFlag("sticking", true)
    if (edge === "end" && axis === "y" && smooth) return easeToEnd()
    scrollTo(axis, edge === "start" ? 0 : maxScroll(metrics[axis]), smooth ? "smooth" : "instant")
  }

  // In capture, the viewport also hears the scrolls of scrollers inside it.
  const onScroll = (event: Event) => {
    if (event.target === viewport) update()
  }
  const onTouchStart = (event: TouchEvent) => {
    touchY = event.touches[0]?.clientY ?? null
  }
  const endTouch = () => {
    touchY = null
    update(true)
  }
  const hover = (hovering: boolean) => (event: PointerEvent) => {
    if (event.pointerType === "touch") return
    setFlag("hovering", hovering)
    refreshVisibility()
  }
  const enter = hover(true)
  const leave = hover(false)

  function bindViewport(el: HTMLElement) {
    viewport = el
    const view = el.ownerDocument.defaultView ?? window
    let counted = false
    const resize = new ResizeObserver(() => {
      if (viewport !== el) return
      rtl = isRTL(el)
      update(true)
      if (!counted) {
        counted = true
        store.set({ counted: true })
      }
    })
    const observeChildren = () => {
      resize.observe(el)
      for (const child of el.children) resize.observe(child)
    }
    observeChildren()
    const children = new MutationObserver(() => {
      observeChildren()
      update(true)
    })
    children.observe(el, { childList: true })

    const scrollable = () => store.get().overflowX || store.get().overflowY
    const tabStop = bindTabStop(el, scrollable)
    let wasScrollable = scrollable()
    const unsubscribe = store.subscribe(() => {
      if (scrollable() === wasScrollable) return
      wasScrollable = scrollable()
      tabStop.check()
    })

    const lift = () => {
      pressed = false
      view.removeEventListener("pointerup", lift, true)
